pub fn request_bytes(pieces: &[Piece]) -> Vec<u8> {
    let mut out = Vec::new();
    for piece in pieces {
        match piece {
            Piece::Bytes(bytes) => out.extend_from_slice(bytes),
            Piece::Repeat(byte, count) => out.extend(std::iter::repeat_n(*byte, *count)),
        }
    }
    out
}
